import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;

public class Main {
    static int passed, failed;
    static boolean prototype;
    interface Checked { void run() throws Exception; }
    static void test(String name, Checked body) {
        try { body.run(); passed++; System.out.println("PASS " + name); }
        catch (Throwable error) { failed++; System.out.println("FAIL " + name + ": " + error); }
    }
    static void eq(Object actual, Object expected) {
        if(actual instanceof Map<?,?> a && expected instanceof Map<?,?> b && !new ArrayList<>(a.keySet()).equals(new ArrayList<>(b.keySet()))) throw new AssertionError("map key order differs");
        if (!Objects.deepEquals(actual, expected)) throw new AssertionError("expected " + show(expected) + ", got " + show(actual));
    }
    static String show(Object value) { return Arrays.deepToString(new Object[]{value}); }
    static void yes(boolean condition) { if (!condition) throw new AssertionError("condition was false"); }
    static void error(Class<? extends Throwable> kind, Checked body) throws Exception {
        try { body.run(); } catch (Throwable e) { if (kind.isInstance(e)) return; throw new AssertionError("expected " + kind.getSimpleName() + ", got " + e,e); }
        throw new AssertionError("expected " + kind.getSimpleName());
    }
    @SafeVarargs static <T> List<T> list(T... values) { return new ArrayList<>(Arrays.asList(values)); }
    static <K,V> Map<K,V> map(Object... values) {
        Map<K,V> result=new LinkedHashMap<>();
        for(int i=0;i<values.length;i+=2) { @SuppressWarnings("unchecked") K k=(K)values[i]; @SuppressWarnings("unchecked") V v=(V)values[i+1]; result.put(k,v); }
        return result;
    }
    static void suites() throws Exception {
        test("correction invalidates prefix", () -> { long[] a0=new long[]{2L,4L,6L}; List<Exercise.Update> a1=list(new Exercise.Update("sum",0,3L),new Exercise.Update("add",0,-5L),new Exercise.Update("sum",0,2L),new Exercise.Update("sum",2,2L)); String before=show(new Object[]{a0,a1}); try { eq(prototype ? Exercise.prototype(a0,a1) : Exercise.solve(a0,a1),list(12L,1L,0L)); } finally { eq(show(new Object[]{a0,a1}),before); } });
        test("empty values", () -> { long[] a0=new long[]{}; List<Exercise.Update> a1=list(new Exercise.Update("sum",0,0L)); String before=show(new Object[]{a0,a1}); try { eq(prototype ? Exercise.prototype(a0,a1) : Exercise.solve(a0,a1),list(0L)); } finally { eq(show(new Object[]{a0,a1}),before); } });
        test("point additions 0", () -> { long[] a0=new long[]{3L,3L,7L,0L,0L,2L,8L,4L}; List<Exercise.Update> a1=list(new Exercise.Update("sum",0,3L),new Exercise.Update("sum",0,4L),new Exercise.Update("sum",0,1L),new Exercise.Update("sum",0,7L),new Exercise.Update("add",0,7L),new Exercise.Update("add",0,6L),new Exercise.Update("sum",0,6L),new Exercise.Update("add",0,3L),new Exercise.Update("add",0,8L),new Exercise.Update("sum",0,3L),new Exercise.Update("sum",0,1L),new Exercise.Update("sum",0,6L),new Exercise.Update("add",0,5L),new Exercise.Update("sum",0,6L),new Exercise.Update("sum",0,7L)); String before=show(new Object[]{a0,a1}); try { eq(prototype ? Exercise.prototype(a0,a1) : Exercise.solve(a0,a1),list(13L,13L,3L,23L,28L,37L,27L,39L,44L,52L)); } finally { eq(show(new Object[]{a0,a1}),before); } });
        test("point additions 1", () -> { long[] a0=new long[]{0L,9L,2L,4L,1L,8L,3L,6L}; List<Exercise.Update> a1=list(new Exercise.Update("sum",0,4L),new Exercise.Update("add",0,0L),new Exercise.Update("add",0,6L),new Exercise.Update("add",0,4L),new Exercise.Update("add",0,7L),new Exercise.Update("add",0,6L),new Exercise.Update("add",0,4L),new Exercise.Update("sum",0,8L),new Exercise.Update("add",0,1L),new Exercise.Update("sum",0,7L),new Exercise.Update("add",0,1L),new Exercise.Update("add",0,6L),new Exercise.Update("sum",0,4L),new Exercise.Update("add",0,8L),new Exercise.Update("add",0,8L)); String before=show(new Object[]{a0,a1}); try { eq(prototype ? Exercise.prototype(a0,a1) : Exercise.solve(a0,a1),list(15L,60L,55L,50L)); } finally { eq(show(new Object[]{a0,a1}),before); } });
        test("point additions 2", () -> { long[] a0=new long[]{1L,5L,8L,7L,6L,6L,7L,9L}; List<Exercise.Update> a1=list(new Exercise.Update("sum",0,7L),new Exercise.Update("add",0,3L),new Exercise.Update("sum",0,4L),new Exercise.Update("sum",0,2L),new Exercise.Update("add",0,8L),new Exercise.Update("sum",0,4L),new Exercise.Update("add",0,8L),new Exercise.Update("add",0,2L),new Exercise.Update("add",0,0L),new Exercise.Update("add",0,4L),new Exercise.Update("add",0,8L),new Exercise.Update("add",0,2L),new Exercise.Update("sum",0,7L),new Exercise.Update("add",0,4L),new Exercise.Update("add",0,6L)); String before=show(new Object[]{a0,a1}); try { eq(prototype ? Exercise.prototype(a0,a1) : Exercise.solve(a0,a1),list(40L,24L,9L,32L,75L)); } finally { eq(show(new Object[]{a0,a1}),before); } });
        test("point additions 3", () -> { long[] a0=new long[]{6L,0L,5L,1L,6L,6L,3L,2L}; List<Exercise.Update> a1=list(new Exercise.Update("sum",0,3L),new Exercise.Update("sum",0,4L),new Exercise.Update("add",0,8L),new Exercise.Update("sum",0,8L),new Exercise.Update("sum",0,2L),new Exercise.Update("add",0,0L),new Exercise.Update("add",0,8L),new Exercise.Update("sum",0,7L),new Exercise.Update("sum",0,8L),new Exercise.Update("sum",0,0L),new Exercise.Update("sum",0,8L),new Exercise.Update("sum",0,6L),new Exercise.Update("add",0,1L),new Exercise.Update("sum",0,5L),new Exercise.Update("sum",0,4L)); String before=show(new Object[]{a0,a1}); try { eq(prototype ? Exercise.prototype(a0,a1) : Exercise.solve(a0,a1),list(11L,12L,37L,14L,43L,45L,0L,45L,40L,35L,29L)); } finally { eq(show(new Object[]{a0,a1}),before); } });
        test("point additions 4", () -> { long[] a0=new long[]{5L,6L,0L,6L,3L,5L,9L,2L}; List<Exercise.Update> a1=list(new Exercise.Update("sum",0,8L),new Exercise.Update("add",0,4L),new Exercise.Update("sum",0,1L),new Exercise.Update("add",0,6L),new Exercise.Update("add",0,0L),new Exercise.Update("sum",0,8L),new Exercise.Update("sum",0,6L),new Exercise.Update("sum",0,3L),new Exercise.Update("sum",0,1L),new Exercise.Update("add",0,0L),new Exercise.Update("sum",0,0L),new Exercise.Update("add",0,1L),new Exercise.Update("add",0,3L),new Exercise.Update("sum",0,8L),new Exercise.Update("add",0,4L)); String before=show(new Object[]{a0,a1}); try { eq(prototype ? Exercise.prototype(a0,a1) : Exercise.solve(a0,a1),list(36L,9L,46L,35L,21L,15L,0L,50L)); } finally { eq(show(new Object[]{a0,a1}),before); } });
        test("point additions 5", () -> { long[] a0=new long[]{1L,6L,4L,3L,7L,9L,6L,0L}; List<Exercise.Update> a1=list(new Exercise.Update("add",0,0L),new Exercise.Update("add",0,8L),new Exercise.Update("sum",0,8L),new Exercise.Update("sum",0,6L),new Exercise.Update("add",0,6L),new Exercise.Update("sum",0,2L),new Exercise.Update("sum",0,6L),new Exercise.Update("add",0,7L),new Exercise.Update("sum",0,5L),new Exercise.Update("add",0,6L),new Exercise.Update("sum",0,7L),new Exercise.Update("add",0,0L),new Exercise.Update("add",0,0L),new Exercise.Update("sum",0,6L),new Exercise.Update("sum",0,6L)); String before=show(new Object[]{a0,a1}); try { eq(prototype ? Exercise.prototype(a0,a1) : Exercise.solve(a0,a1),list(44L,38L,21L,44L,42L,63L,57L,57L)); } finally { eq(show(new Object[]{a0,a1}),before); } });
        test("point additions 6", () -> { long[] a0=new long[]{1L,0L,9L,2L,9L,0L,1L,7L}; List<Exercise.Update> a1=list(new Exercise.Update("sum",0,6L),new Exercise.Update("sum",0,5L),new Exercise.Update("sum",0,3L),new Exercise.Update("add",0,6L),new Exercise.Update("add",0,7L),new Exercise.Update("sum",0,6L),new Exercise.Update("add",0,4L),new Exercise.Update("add",0,0L),new Exercise.Update("sum",0,6L),new Exercise.Update("add",0,7L),new Exercise.Update("add",0,4L),new Exercise.Update("sum",0,8L),new Exercise.Update("sum",0,5L),new Exercise.Update("add",0,0L),new Exercise.Update("sum",0,8L)); String before=show(new Object[]{a0,a1}); try { eq(prototype ? Exercise.prototype(a0,a1) : Exercise.solve(a0,a1),list(21L,21L,10L,34L,38L,57L,49L,57L)); } finally { eq(show(new Object[]{a0,a1}),before); } });
        test("point additions 7", () -> { long[] a0=new long[]{6L,1L,1L,2L,7L,0L,0L,9L}; List<Exercise.Update> a1=list(new Exercise.Update("sum",0,2L),new Exercise.Update("add",0,7L),new Exercise.Update("sum",0,0L),new Exercise.Update("sum",0,5L),new Exercise.Update("add",0,7L),new Exercise.Update("add",0,7L),new Exercise.Update("sum",0,8L),new Exercise.Update("add",0,6L),new Exercise.Update("add",0,8L),new Exercise.Update("sum",0,8L),new Exercise.Update("add",0,8L),new Exercise.Update("add",0,2L),new Exercise.Update("add",0,4L),new Exercise.Update("add",0,8L),new Exercise.Update("add",0,2L)); String before=show(new Object[]{a0,a1}); try { eq(prototype ? Exercise.prototype(a0,a1) : Exercise.solve(a0,a1),list(7L,0L,24L,47L,61L)); } finally { eq(show(new Object[]{a0,a1}),before); } });
        test("point additions 8", () -> { long[] a0=new long[]{3L,3L,0L,3L,5L,1L,5L,1L}; List<Exercise.Update> a1=list(new Exercise.Update("add",0,4L),new Exercise.Update("add",0,5L),new Exercise.Update("add",0,6L),new Exercise.Update("add",0,4L),new Exercise.Update("sum",0,1L),new Exercise.Update("add",0,5L),new Exercise.Update("sum",0,1L),new Exercise.Update("sum",0,4L),new Exercise.Update("sum",0,3L),new Exercise.Update("add",0,7L),new Exercise.Update("sum",0,5L),new Exercise.Update("sum",0,2L),new Exercise.Update("add",0,4L),new Exercise.Update("add",0,1L),new Exercise.Update("sum",0,1L)); String before=show(new Object[]{a0,a1}); try { eq(prototype ? Exercise.prototype(a0,a1) : Exercise.solve(a0,a1),list(22L,27L,33L,30L,45L,37L,39L)); } finally { eq(show(new Object[]{a0,a1}),before); } });
        test("point additions 9", () -> { long[] a0=new long[]{3L,2L,3L,1L,2L,3L,3L,6L}; List<Exercise.Update> a1=list(new Exercise.Update("sum",0,6L),new Exercise.Update("sum",0,7L),new Exercise.Update("sum",0,7L),new Exercise.Update("sum",0,1L),new Exercise.Update("sum",0,0L),new Exercise.Update("sum",0,8L),new Exercise.Update("sum",0,8L),new Exercise.Update("sum",0,6L),new Exercise.Update("sum",0,3L),new Exercise.Update("add",0,8L),new Exercise.Update("sum",0,8L),new Exercise.Update("sum",0,1L),new Exercise.Update("add",0,7L),new Exercise.Update("add",0,8L),new Exercise.Update("add",0,8L)); String before=show(new Object[]{a0,a1}); try { eq(prototype ? Exercise.prototype(a0,a1) : Exercise.solve(a0,a1),list(14L,17L,17L,3L,0L,23L,23L,14L,8L,31L,11L)); } finally { eq(show(new Object[]{a0,a1}),before); } });
        test("point additions 10", () -> { long[] a0=new long[]{6L,0L,6L,3L,2L,9L,2L,8L}; List<Exercise.Update> a1=list(new Exercise.Update("add",0,2L),new Exercise.Update("add",0,5L),new Exercise.Update("add",0,2L),new Exercise.Update("sum",0,5L),new Exercise.Update("sum",0,6L),new Exercise.Update("add",0,7L),new Exercise.Update("sum",0,5L),new Exercise.Update("add",0,4L),new Exercise.Update("sum",0,6L),new Exercise.Update("add",0,8L),new Exercise.Update("sum",0,7L),new Exercise.Update("sum",0,2L),new Exercise.Update("sum",0,5L),new Exercise.Update("sum",0,2L),new Exercise.Update("add",0,4L)); String before=show(new Object[]{a0,a1}); try { eq(prototype ? Exercise.prototype(a0,a1) : Exercise.solve(a0,a1),list(26L,35L,33L,46L,56L,34L,45L,34L)); } finally { eq(show(new Object[]{a0,a1}),before); } });
        test("point additions 11", () -> { long[] a0=new long[]{1L,8L,3L,3L,8L,7L,2L,8L}; List<Exercise.Update> a1=list(new Exercise.Update("add",0,5L),new Exercise.Update("sum",0,2L),new Exercise.Update("add",0,5L),new Exercise.Update("add",0,1L),new Exercise.Update("add",0,1L),new Exercise.Update("add",0,3L),new Exercise.Update("sum",0,3L),new Exercise.Update("sum",0,8L),new Exercise.Update("sum",0,7L),new Exercise.Update("sum",0,1L),new Exercise.Update("sum",0,1L),new Exercise.Update("add",0,5L),new Exercise.Update("add",0,0L),new Exercise.Update("add",0,1L),new Exercise.Update("sum",0,8L)); String before=show(new Object[]{a0,a1}); try { eq(prototype ? Exercise.prototype(a0,a1) : Exercise.solve(a0,a1),list(14L,27L,55L,47L,16L,16L,61L)); } finally { eq(show(new Object[]{a0,a1}),before); } });
        test("invalid input", () -> { long[] a0=new long[]{}; List<Exercise.Update> a1=list(new Exercise.Update("add",0,1L)); String before=show(new Object[]{a0,a1}); try { error(IllegalArgumentException.class, () -> { Object ignored = prototype ? Exercise.prototype(a0,a1) : Exercise.solve(a0,a1); }); } finally { eq(show(new Object[]{a0,a1}),before); } });
        test("invalid input", () -> { long[] a0=new long[]{1L}; List<Exercise.Update> a1=list(new Exercise.Update("sum",1,0L)); String before=show(new Object[]{a0,a1}); try { error(IllegalArgumentException.class, () -> { Object ignored = prototype ? Exercise.prototype(a0,a1) : Exercise.solve(a0,a1); }); } finally { eq(show(new Object[]{a0,a1}),before); } });
        test("invalid input", () -> { long[] a0=new long[]{1L}; List<Exercise.Update> a1=list(new Exercise.Update("set",0,1L)); String before=show(new Object[]{a0,a1}); try { error(IllegalArgumentException.class, () -> { Object ignored = prototype ? Exercise.prototype(a0,a1) : Exercise.solve(a0,a1); }); } finally { eq(show(new Object[]{a0,a1}),before); } });

        if(!prototype) test("final scale and structure boundary", () -> { long[] a=new long[10000];List<Exercise.Update> c=new ArrayList<>();for(int i=0;i<a.length;i++)c.add(new Exercise.Update("add",i,1));c.add(new Exercise.Update("sum",0,10000));c.add(new Exercise.Update("add",9999,-2));c.add(new Exercise.Update("sum",9999,10000));eq(Exercise.solve(a,c),list(10000L,-1L));eq(a[9999],0L); });
    }
    public static void main(String[] args) throws Exception {
        String stage="final";
        if(args.length!=0) {
            if(args.length!=2 || !args[0].equals("--stage")) { System.err.println("Usage: java Main --stage prototype|final"); System.exit(2); }
            stage=args[1];
        }
        if(!stage.equals("prototype") && !stage.equals("final")) { System.err.println("Unknown stage: " + stage); System.exit(2); }
        prototype=stage.equals("prototype"); suites();
        System.out.println("RESULT stage="+stage+" passed="+passed+" failed="+failed);
        if(failed>0 || passed==0) System.exit(1);
    }
}
